// sprite.js — the runner, embedded as a data URI.
// Inlined so CSS masks work when you just double-click index.html
// (browsers block file:// mask fetches cross-origin). runner.png is kept
// in the folder too, for reuse in other tools.
window.RUNNER_SPRITE = "data:image/png;base64,";
// apply immediately so runners never flash as solid boxes before game.js runs
document.documentElement.style.setProperty("--runner-mask", "url('"+window.RUNNER_SPRITE+"')");
